        buffer_3_inst <=
          (matches_3_0 ? io_enqData_0_inst : 32'h0)
          | (matches_3_1 ? io_enqData_1_inst : 32'h0)
          | (matches_3_2 ? io_enqData_2_inst : 32'h0)
