        buffer_3_brchFwd <=
          matches_3_0 & io_enqData_0_brchFwd | matches_3_1 & io_enqData_1_brchFwd
          | matches_3_2 & io_enqData_2_brchFwd | matches_3_3 & io_enqData_3_brchFwd;
