        buffer_4_addr <=
          (matches_4_0 ? io_enqData_0_addr : 32'h0)
          | (matches_4_1 ? io_enqData_1_addr : 32'h0)
          | (matches_4_2 ? io_enqData_2_addr : 32'h0)
          | (matches_4_3 ? io_enqData_3_addr : 32'h0);
        buffer_4_inst <=
          (matches_4_0 ? io_enqData_0_inst : 32'h0)
          | (matches_4_1 ? io_enqData_1_inst : 32'h0)
          | (matches_4_2 ? io_enqData_2_inst : 32'h0)
          | (matches_4_3 ? io_enqData_3_inst : 32'h0);
        buffer_4_brchFwd <=
          matches_4_0 & io_enqData_0_brchFwd | matches_4_1 & io_enqData_1_brchFwd
          | matches_4_2 & io_enqData_2_brchFwd | matches_4_3 & io_enqData_3_brchFwd;
