        buffer_5_addr <=
          (matches_5_0 ? io_enqData_0_addr : 32'h0)
          | (matches_5_1 ? io_enqData_1_addr : 32'h0)
          | (matches_5_2 ? io_enqData_2_addr : 32'h0)
          | (matches_5_3 ? io_enqData_3_addr : 32'h0);
        buffer_5_inst <=
          (matches_5_0 ? io_enqData_0_inst : 32'h0)
          | (matches_5_1 ? io_enqData_1_inst : 32'h0)
          | (matches_5_2 ? io_enqData_2_inst : 32'h0)
          | (matches_5_3 ? io_enqData_3_inst : 32'h0);
        buffer_5_brchFwd <=
          matches_5_0 & io_enqData_0_brchFwd | matches_5_1 & io_enqData_1_brchFwd
          | matches_5_2 & io_enqData_2_brchFwd | matches_5_3 & io_enqData_3_brchFwd;
