        buffer_6_addr <=
          (matches_6_0 ? io_enqData_0_addr : 32'h0)
          | (matches_6_1 ? io_enqData_1_addr : 32'h0)
          | (matches_6_2 ? io_enqData_2_addr : 32'h0)
          | (matches_6_3 ? io_enqData_3_addr : 32'h0);
        buffer_6_inst <=
          (matches_6_0 ? io_enqData_0_inst : 32'h0)
          | (matches_6_1 ? io_enqData_1_inst : 32'h0)
          | (matches_6_2 ? io_enqData_2_inst : 32'h0)
          | (matches_6_3 ? io_enqData_3_inst : 32'h0);
        buffer_6_brchFwd <=
          matches_6_0 & io_enqData_0_brchFwd | matches_6_1 & io_enqData_1_brchFwd
          | matches_6_2 & io_enqData_2_brchFwd | matches_6_3 & io_enqData_3_brchFwd;
      end
      if (|{matches_7_3, matches_7_2, matches_7_1, matches_7_0}) begin
        buffer_7_addr <=
          (matches_7_0 ? io_enqData_0_addr : 32'h0)
          | (matches_7_1 ? io_enqData_1_addr : 32'h0)
          | (matches_7_2 ? io_enqData_2_addr : 32'h0)
          | (matches_7_3 ? io_enqData_3_addr : 32'h0);
        buffer_7_inst <=
          (matches_7_0 ? io_enqData_0_inst : 32'h0)
          | (matches_7_1 ? io_enqData_1_inst : 32'h0)
          | (matches_7_2 ? io_enqData_2_inst : 32'h0)
          | (matches_7_3 ? io_enqData_3_inst : 32'h0);
        buffer_7_brchFwd <=
          matches_7_0 & io_enqData_0_brchFwd | matches_7_1 & io_enqData_1_brchFwd
