  assign io_nEnqueued = nEnqueued;
  assign io_nSpace = 4'h8 - nEnqueued;
  assign io_dataOut_0_addr =
    deqPtr[0]
      ? _shifted_WIRE_1_addr
      : deqPtr[1] ? _shifted_T_7_addr : deqPtr[2] ? buffer_4_addr : buffer_0_addr;
  assign io_dataOut_0_inst =
    deqPtr[0]
      ? _shifted_WIRE_1_inst
      : deqPtr[1] ? _shifted_T_7_inst : deqPtr[2] ? buffer_4_inst : buffer_0_inst;
  assign io_dataOut_0_brchFwd =
    deqPtr[0]
      ? _shifted_WIRE_1_brchFwd
      : deqPtr[1]
