          : deqPtr[2] ? buffer_4_brchFwd : buffer_0_brchFwd;
  assign io_dataOut_1_addr = deqPtr[0] ? _shifted_WIRE_2_addr : _shifted_WIRE_1_addr;
  assign io_dataOut_1_inst = deqPtr[0] ? _shifted_WIRE_2_inst : _shifted_WIRE_1_inst;
  assign io_dataOut_1_brchFwd =
    deqPtr[0] ? _shifted_WIRE_2_brchFwd : _shifted_WIRE_1_brchFwd;
  assign io_dataOut_2_addr = deqPtr[0] ? _shifted_WIRE_3_addr : _shifted_WIRE_2_addr;
  assign io_dataOut_2_inst = deqPtr[0] ? _shifted_WIRE_3_inst : _shifted_WIRE_2_inst;
  assign io_dataOut_2_brchFwd =
    deqPtr[0] ? _shifted_WIRE_3_brchFwd : _shifted_WIRE_2_brchFwd;
  assign io_dataOut_3_addr =
    deqPtr[0]
      ? (deqPtr[1] ? (deqPtr[2] ? buffer_2_addr : buffer_6_addr) : _shifted_T_13_addr)
      : _shifted_WIRE_3_addr;
  assign io_dataOut_3_inst =
    deqPtr[0]
      ? (deqPtr[1] ? (deqPtr[2] ? buffer_2_inst : buffer_6_inst) : _shifted_T_13_inst)
