    .clock                           (clock),
    .reset                           (reset),
    .io_fetchFault_valid             (io_fault_valid),
    .io_fetchFault_bits              (io_fault_bits),
    .io_csr_value_0                  (io_csr_value_0),
    .io_iflush_valid                 (io_iflush_valid | io_debug_pc_valid),
    .io_iflush_bits
      (io_iflush_valid ? io_iflush_pcNext : io_debug_pc_valid ? io_debug_pc_bits : 32'h0),
    .io_branch_valid                 (branch_valid),
    .io_branch_bits
