module FabricArbiter(
  input          io_source_0_readDataAddr_valid,
  input  [31:0]  io_source_0_readDataAddr_bits,
  output [127:0] io_source_0_readData_bits,
  input          io_source_0_writeDataAddr_valid,
  input  [31:0]  io_source_0_writeDataAddr_bits,
  input  [127:0] io_source_0_writeDataBits,
  input  [15:0]  io_source_0_writeDataStrb,
  input          io_source_1_readDataAddr_valid,
  input  [31:0]  io_source_1_readDataAddr_bits,
  output         io_source_1_readData_valid,
  output [127:0] io_source_1_readData_bits,
  input          io_source_1_writeDataAddr_valid,
  input  [31:0]  io_source_1_writeDataAddr_bits,
  input  [127:0] io_source_1_writeDataBits,
  input  [15:0]  io_source_1_writeDataStrb,
  input          io_source_2_readDataAddr_valid,
  input  [31:0]  io_source_2_readDataAddr_bits,
  output         io_source_2_readData_valid,
  output [127:0] io_source_2_readData_bits,
  input          io_source_2_writeDataAddr_valid,
  input  [31:0]  io_source_2_writeDataAddr_bits,
  input  [127:0] io_source_2_writeDataBits,
  input  [15:0]  io_source_2_writeDataStrb,
  output         io_fabricBusy_1,
                 io_port_readDataAddr_valid,
  output [31:0]  io_port_readDataAddr_bits,
  input          io_port_readData_valid,
  input  [127:0] io_port_readData_bits,
  output         io_port_writeDataAddr_valid,
  output [31:0]  io_port_writeDataAddr_bits,
  output [127:0] io_port_writeDataBits,
  output [15:0]  io_port_writeDataStrb
);

  wire sourceValid_0 = io_source_0_readDataAddr_valid | io_source_0_writeDataAddr_valid;
  wire sourceValid_1 = io_source_1_readDataAddr_valid | io_source_1_writeDataAddr_valid;
  wire sourceValid_2 = io_source_2_readDataAddr_valid | io_source_2_writeDataAddr_valid;
  assign io_source_0_readData_bits = io_port_readData_bits;
  assign io_source_1_readData_valid = io_port_readData_valid;
  assign io_source_1_readData_bits = io_port_readData_bits;
  assign io_source_2_readData_valid = io_port_readData_valid;
  assign io_source_2_readData_bits = io_port_readData_bits;
  assign io_fabricBusy_1 = sourceValid_0;
  assign io_port_readDataAddr_valid =
    sourceValid_0
      ? io_source_0_readDataAddr_valid
      : sourceValid_1
          ? io_source_1_readDataAddr_valid
          : sourceValid_2 & io_source_2_readDataAddr_valid;
  assign io_port_readDataAddr_bits =
    sourceValid_0
      ? io_source_0_readDataAddr_bits
      : sourceValid_1
          ? io_source_1_readDataAddr_bits
          : sourceValid_2 ? io_source_2_readDataAddr_bits : 32'h0;
  assign io_port_writeDataAddr_valid =
    sourceValid_0
      ? io_source_0_writeDataAddr_valid
      : sourceValid_1
          ? io_source_1_writeDataAddr_valid
          : sourceValid_2 & io_source_2_writeDataAddr_valid;
  assign io_port_writeDataAddr_bits =
    sourceValid_0
      ? io_source_0_writeDataAddr_bits
      : sourceValid_1
          ? io_source_1_writeDataAddr_bits
          : sourceValid_2 ? io_source_2_writeDataAddr_bits : 32'h0;
  assign io_port_writeDataBits =
    sourceValid_0
      ? io_source_0_writeDataBits
      : sourceValid_1
          ? io_source_1_writeDataBits
          : sourceValid_2 ? io_source_2_writeDataBits : 128'h0;
  assign io_port_writeDataStrb =
    sourceValid_0
      ? io_source_0_writeDataStrb
      : sourceValid_1
          ? io_source_1_writeDataStrb
          : sourceValid_2 ? io_source_2_writeDataStrb : 16'h0;
endmodule

module IBus2Axi(
  input          clock,
                 reset,
                 io_ibus_valid,
  output         io_ibus_ready,
  input  [31:0]  io_ibus_addr,
  output [127:0] io_ibus_rdata,
  output         io_ibus_fault_valid,
  input          io_axi_addr_ready,
  output         io_axi_addr_valid,
  output [31:0]  io_axi_addr_bits_addr,
  input          io_axi_data_valid,
  input  [127:0] io_axi_data_bits_data,
  input  [1:0]   io_axi_data_bits_resp
);

  reg          sraddrActive;
  reg  [31:0]  saddrReg;
  reg  [127:0] sdata;
  reg  [1:0]   sresp;
  reg          sdataValid;
  wire [31:0]  saddr = {io_ibus_addr[31:4], 4'h0};
  wire         io_ibus_ready_0 =
    (io_axi_data_valid & sraddrActive | sdataValid) & saddr == saddrReg;
  wire         io_axi_addr_valid_0 =
    io_ibus_valid & ~sraddrActive & (~sdataValid | saddr != saddrReg);
  wire         _saddrReg_T = io_axi_addr_ready & io_axi_addr_valid_0;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      sraddrActive <= 1'h0;
      saddrReg <= 32'h0;
      sdata <= 128'h0;
      sresp <= 2'h0;
      sdataValid <= 1'h0;
    end
    else begin
      sraddrActive <= ~io_axi_data_valid & (_saddrReg_T | sraddrActive);
      if (_saddrReg_T)
        saddrReg <= saddr;
      if (io_axi_data_valid) begin
        sdata <= io_axi_data_bits_data;
        sresp <= io_axi_data_bits_resp;
      end
      sdataValid <=
        io_axi_data_valid
          ? ~io_ibus_ready_0
          : ~(io_ibus_ready_0 & io_ibus_valid | _saddrReg_T) & sdataValid;
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      if (reset) begin
        sraddrActive = 1'h0;
        saddrReg = 32'h0;
        sdata = 128'h0;
        sresp = 2'h0;
        sdataValid = 1'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_ibus_ready = io_ibus_ready_0;
  assign io_ibus_rdata = sdata;
  assign io_ibus_fault_valid =
    io_ibus_ready_0 & (|(io_axi_data_valid ? io_axi_data_bits_resp : sresp));
  assign io_axi_addr_valid = io_axi_addr_valid_0;
  assign io_axi_addr_bits_addr = saddr;
endmodule

module SRAM_2048x128(
  input          clock,
                 reset,
  input  [10:0]  io_addr,
  input          io_enable,
                 io_write,
  input  [127:0] io_wdata,
  input  [15:0]  io_wmask,
  output [127:0] io_rdata
);

  wire [127:0]      _sramModules_3_rdata;
  wire [127:0]      _sramModules_2_rdata;
  wire [127:0]      _sramModules_1_rdata;
  wire [127:0]      _sramModules_0_rdata;
  reg  [1:0]        selectedSramRead;
  wire [3:0][127:0] _GEN =
    {{_sramModules_3_rdata},
     {_sramModules_2_rdata},
     {_sramModules_1_rdata},
     {_sramModules_0_rdata}};
  always @(posedge clock or posedge reset) begin
    if (reset)
      selectedSramRead <= 2'h0;
    else
      selectedSramRead <= io_addr[10:9];
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      if (reset)
        selectedSramRead = 2'h0;
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  Sram #(
    .GLOBAL_BASE_ADDR(65536),
    .NUM_ENTRIES(512)
  ) sramModules_0 (
    .clock  (clock),
    .enable (io_addr[10:9] == 2'h0 & io_enable),
    .write  (io_write),
    .addr   (io_addr[8:0]),
    .wdata  (io_wdata),
    .wmask  (io_wmask),
    .rdata  (_sramModules_0_rdata),
    .rvalid (/* unused */)
  );
  Sram #(
    .GLOBAL_BASE_ADDR(73728),
    .NUM_ENTRIES(512)
  ) sramModules_1 (
    .clock  (clock),
    .enable (io_addr[10:9] == 2'h1 & io_enable),
    .write  (io_write),
    .addr   (io_addr[8:0]),
    .wdata  (io_wdata),
    .wmask  (io_wmask),
    .rdata  (_sramModules_1_rdata),
    .rvalid (/* unused */)
  );
  Sram #(
    .GLOBAL_BASE_ADDR(81920),
    .NUM_ENTRIES(512)
  ) sramModules_2 (
    .clock  (clock),
    .enable (io_addr[10:9] == 2'h2 & io_enable),
    .write  (io_write),
    .addr   (io_addr[8:0]),
    .wdata  (io_wdata),
    .wmask  (io_wmask),
    .rdata  (_sramModules_2_rdata),
    .rvalid (/* unused */)
  );
  Sram #(
    .GLOBAL_BASE_ADDR(90112),
    .NUM_ENTRIES(512)
  ) sramModules_3 (
    .clock  (clock),
    .enable ((&(io_addr[10:9])) & io_enable),
    .write  (io_write),
    .addr   (io_addr[8:0]),
    .wdata  (io_wdata),
    .wmask  (io_wmask),
    .rdata  (_sramModules_3_rdata),
    .rvalid (/* unused */)
  );
  assign io_rdata = _GEN[selectedSramRead];
endmodule

